UPDATE POSTS
TITLE = #{title}, CONTENT = #{content}, FILE_GROUP_ID = #{fileGroupId}, UPDATED_AT = NOW()
WHERE POST_ID = #{postId}

	UPDATE  POSTS
	   SET   TITLE      = #{title}
   			,UPDATED_AT = NOW()
	 WHERE  POST_ID    	= #{postId}

	UPDATE  POSTS
	   SET  CATEGORY_ID    = #{categoryId}
	   	    ,PARENT_POST_ID = #{parentPostId}
	   		,SORT_SEQ       = #{sortSeq}
   			,UPDATED_AT 	= NOW()
	 WHERE  POST_ID    		= #{postId}

mapper.select:
SELECT POST_ID ,TITLE ,AUTHOR_ID ,SORT_SEQ ,VIEW_COUNT ,UPDATED_AT FROM POSTS WHERE DEL_YN = 'N'
AND PARENT_POST_ID = #{parentPostId}
AND PARENT_POST_ID IS NULL AND CATEGORY_ID = #{categoryId}
ORDER BY SORT_SEQ ASC

WITH RECURSIVE PARENT_CATEGORIES AS ( SELECT * FROM CATEGORIES WHERE CATEGORY_ID = #{categoryId}
UNION ALL
SELECT C.* FROM CATEGORIES C INNER JOIN PARENT_CATEGORIES PC ON C.PARENT_CATEGORY_ID = PC.CATEGORY_ID ) SELECT P.POST_ID, P.PARENT_POST_ID, P.CATEGORY_ID, P.SORT_SEQ, P.AUTHOR_ID, P.FILE_GROUP_ID, P.TITLE FROM PARENT_CATEGORIES PC LEFT OUTER JOIN POSTS P ON PC.category_id = P.category_id WHERE P.POST_ID IS NOT NULL AND P.DEL_YN = 'N' ORDER BY P.CATEGORY_ID, P.SORT_SEQ;

